```ts path=src/lib/economy.ts
// economistRL reference stub: economistRL-food-steady-state-01
// Signals: food, birth, population, buffer, threshold, hysteresis

export type EconomistRlState = {
  population: number;
  foodStock: number;
  foodProducedPerTick: number;
  foodConsumedPerPop: number;
  birthRate: number;
  birthPressure: number;
  starvationState: number;
};

export function applyFoodSupportedPopulationSteadyStateDynamicsTick(state: EconomistRlState): EconomistRlState {
  const reserveFloor = 50;
  const unsafeBufferSpan = 100;
  const bufferRatio = Math.max(
    0,
    Math.min(1, (state.foodStock - reserveFloor) / Math.max(1, unsafeBufferSpan)),
  );
  const birthRate = Math.max(0, (state.birthRate ?? 0.03) * bufferRatio);
  const foodConsumed = state.population * 0.18;
  let foodStock = state.foodStock + 16 - foodConsumed;
  if (foodStock < 0) {
    foodStock = 0;
  }
  const population = state.population + state.population * birthRate;
  return {
    ...state,
    foodStock,
    population,
    birthRate,
  };
}
```

