import { applyFoodSupportedPopulationSteadyStateDynamicsTick } from '../../src/lib/economy';

describe('economistRL economistRL-food-steady-state-01', () => {
  it('birth_rate_changes_when_food_buffer_chan', () => {
    const safe = applyFoodSupportedPopulationSteadyStateDynamicsTick({
      foodStock: 200,
      population: 100,
      birthRate: 0.04,
    });
    const unsafe = applyFoodSupportedPopulationSteadyStateDynamicsTick({
      foodStock: 40,
      population: 100,
      birthRate: 0.04,
    });
    expect(safe.birthRate).toBeGreaterThanOrEqual(unsafe.birthRate);
    expect(safe.foodStock).toBeGreaterThanOrEqual(0);
  });
});
```

