// economistRL reference stub: economistRL-market-elasticity-pricing-002
// Signals: stock, desiredStock, price, elasticity, scarcity, surplus

export type EconomistRlState = {
  currentStock: number;
  desiredStock: number;
  lastPrice: number;
  demand: number;
  scarcityPressure: number;
  surplusPressure: number;
  priceFloor: number;
  priceCap: number;
};

export function applyMarketElasticityPricingCase002Tick(state: EconomistRlState): EconomistRlState {
  const reserveFloor = 50;
  const unsafeBufferSpan = 100;
  const bufferRatio = Math.max(
    0,
    Math.min(1, (state.foodStock - reserveFloor) / Math.max(1, unsafeBufferSpan)),
  );
  const birthRate = Math.max(0, (state.birthRate ?? 0.03) * bufferRatio);
  const foodConsumed = state.population * 0.18;
  let foodStock = state.foodStock + 16 - foodConsumed;
  if (foodStock < 0) {
    foodStock = 0;
  }
  const population = state.population + state.population * birthRate;
  return {
    ...state,
    foodStock,
    population,
    birthRate,
  };
}
