// economistRL reference stub: economistRL-labor-wage-productivity-033
// Signals: wage, morale, productivity, output, threshold, penalty

export type EconomistRlState = {
  wage: number;
  expectedWage: number;
  morale: number;
  productivity: number;
  goldUpkeep: number;
  workerOutput: number;
  jobAssignment: number;
};

export function applyLaborWageProductivityCase033Tick(state: EconomistRlState): EconomistRlState {
  const reserveFloor = 50;
  const unsafeBufferSpan = 100;
  const bufferRatio = Math.max(
    0,
    Math.min(1, (state.foodStock - reserveFloor) / Math.max(1, unsafeBufferSpan)),
  );
  const birthRate = Math.max(0, (state.birthRate ?? 0.03) * bufferRatio);
  const foodConsumed = state.population * 0.18;
  let foodStock = state.foodStock + 16 - foodConsumed;
  if (foodStock < 0) {
    foodStock = 0;
  }
  const population = state.population + state.population * birthRate;
  return {
    ...state,
    foodStock,
    population,
    birthRate,
  };
}
