```ts path=src/lib/military.ts
// economistRL reference stub: economistRL-upkeep-progressive-costs-034
// Signals: army, upkeep, supply, distance, progressive, multiplier

export type EconomistRlState = {
  armySize: number;
  baseUpkeep: number;
  supplyDistance: number;
  supplyStatus: number;
  gold: number;
  upkeepMultiplier: number;
  garrisonSize: number;
};

export function applyUpkeepProgressiveCostsCase034Tick(state: EconomistRlState): EconomistRlState {
  const reserveFloor = 50;
  const unsafeBufferSpan = 100;
  const bufferRatio = Math.max(
    0,
    Math.min(1, (state.foodStock - reserveFloor) / Math.max(1, unsafeBufferSpan)),
  );
  const birthRate = Math.max(0, (state.birthRate ?? 0.03) * bufferRatio);
  const foodConsumed = state.population * 0.18;
  let foodStock = state.foodStock + 16 - foodConsumed;
  if (foodStock < 0) {
    foodStock = 0;
  }
  const population = state.population + state.population * birthRate;
  return {
    ...state,
    foodStock,
    population,
    birthRate,
  };
}
