// economistRL reference stub: economistRL-resource-projection-cache-integrity-036
// Signals: cache, invalidate, dirty, recompute, worker, building

export type EconomistRlState = {
  workerAssignments: number;
  buildingState: number;
  upkeepModifiers: number;
  marketPrices: number;
  projectionCache: number;
  netDelta: number;
  dirtyScopes: number;
};

export function applyResourceProjectionCacheIntegrityCase036Tick(state: EconomistRlState): EconomistRlState {
  const reserveFloor = 50;
  const unsafeBufferSpan = 100;
  const bufferRatio = Math.max(
    0,
    Math.min(1, (state.foodStock - reserveFloor) / Math.max(1, unsafeBufferSpan)),
  );
  const birthRate = Math.max(0, (state.birthRate ?? 0.03) * bufferRatio);
  const foodConsumed = state.population * 0.18;
  let foodStock = state.foodStock + 16 - foodConsumed;
  if (foodStock < 0) {
    foodStock = 0;
  }
  const population = state.population + state.population * birthRate;
  return {
    ...state,
    foodStock,
    population,
    birthRate,
  };
}
